import 'dart:js_interop';

import 'package:flutter/foundation.dart';
import 'package:web/web.dart' as web;

/// 基于 localStorage 的缓存实现（仅限 Web 平台）。
class CacheService {
  /// 缓存键。
  final String filePath;

  /// 创建以 `filePath` 为键的 localStorage 缓存。
  CacheService({required this.filePath});

  /// 读取缓存内容；键不存在或为空返回 `null`。
  Future<String?> load() async {
    try {
      final raw = web.window.localStorage.getItem(filePath.toJS)?.toDart;
      if (raw == null || raw.isEmpty) return null;
      return raw;
    } catch (e) {
      debugPrint('Cache load error: $e');
      return null;
    }
  }

  /// 写入缓存内容；失败仅记录日志不抛出。
  Future<void> save(String data) async {
    try {
      web.window.localStorage.setItem(filePath.toJS, data.toJS);
    } catch (e) {
      debugPrint('Cache save error: $e');
    }
  }
}

import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:http/http.dart' as http;
import 'package:qtconsult_studio/qtconsult_studio.dart';

List<Task> makeTestTasks() {
  return [
    Task(
      id: 'o1',
      title: '调研卡片',
      description: '测试描述',
      type: 'clarify',
      tags: {'source': '访谈'},
      status: 'pending',
    ),
    Task(
      id: 'o2',
      title: '现实卡片',
      type: 'research',
      tags: {'source': '审计'},
      status: 'confirmed',
    ),
    Task(
      id: 'i1',
      title: '洞察测试',
      type: 'research',
      tags: {'domain': '技术领域', 'rootCause': '根因', 'impact': '影响'},
    ),
    Task(
      id: 's1',
      title: '方案A',
      type: 'decide',
      tags: {'advantage': '优势', 'isSelected': 'true', 'clientNote': ''},
    ),
    Task(
      id: 't1',
      title: '任务1',
      type: 'execute',
      assignee: '某人',
      status: 'doing',
      tags: {'progress': '0.5'},
    ),
  ];
}

class _MockClient extends http.BaseClient {
  final requests = <http.BaseRequest>[];

  @override
  Future<http.StreamedResponse> send(http.BaseRequest request) async {
    requests.add(request);
    final body = jsonEncode({});
    final stream = http.ByteStream.fromBytes(utf8.encode(body));
    final headers = {'content-type': 'application/json; charset=utf-8'};
    return http.StreamedResponse(stream, 200, headers: headers);
  }
}

void main() {
  test('toggleClarifyConfirm 切换状态', () {
    final cubit = ConsultCubit(makeTestTasks(), CacheService(filePath: ''));
    addTearDown(cubit.close);
    expect(cubit.state.tasks[0].status, 'pending');

    cubit.toggleClarifyConfirm('o1');
    expect(cubit.state.tasks[0].status, 'confirmed');
  });

  test('toggleStrategySelect 切换选中状态', () {
    final cubit = ConsultCubit(makeTestTasks(), CacheService(filePath: ''));
    addTearDown(cubit.close);
    expect(cubit.state.tasks[3].tags['isSelected'], 'true');

    cubit.toggleStrategySelect('s1');
    expect(cubit.state.tasks[3].tags['isSelected'], isNull);
  });

  test('updateClientNote 更新备注', () {
    final cubit = ConsultCubit(makeTestTasks(), CacheService(filePath: ''));
    addTearDown(cubit.close);
    expect(cubit.state.tasks[3].tags['clientNote'], '');

    cubit.updateClientNote('s1', '客户要求调整方案');
    expect(cubit.state.tasks[3].tags['clientNote'], '客户要求调整方案');
  });

  test('flush 保存到缓存', () async {
    final tmpDir = Directory.systemTemp.createTempSync('qtconsult_test_');
    addTearDown(() => tmpDir.deleteSync(recursive: true));
    final cachePath = '${tmpDir.path}/cache.json';
    final cache = CacheService(filePath: cachePath);
    final cubit = ConsultCubit(makeTestTasks(), cache);
    addTearDown(cubit.close);

    cubit.toggleClarifyConfirm('o1');
    await cubit.flush();

    final cachedRaw = await cache.load();
    expect(cachedRaw, isNotNull);
    final decoded = jsonDecode(cachedRaw!) as List<dynamic>;
    final list = decoded
        .map((e) => Task.fromJson(e as Map<String, dynamic>))
        .toList();
    expect(list[0].status, 'confirmed');
    expect(cubit.state.hasUnsavedChanges, false);
  });

  test('flush 通过 provider 更新卡片', () async {
    final mock = _MockClient();
    final provider = ProviderService(
      baseUrl: 'http://localhost:8756',
      client: mock,
    );
    final cubit = ConsultCubit(
      makeTestTasks(),
      CacheService(filePath: ''),
      provider: provider,
      workspaceId: 'ws1',
      projectId: 'test',
    );
    addTearDown(cubit.close);

    cubit.toggleClarifyConfirm('o1');
    await cubit.flush();

    final match = mock.requests.any(
      (r) =>
          r.url.toString() ==
              'http://localhost:8756/project/src/file147' &&
          r.method == 'PUT',
    );
    expect(match, true);
  });

  test('交互后标记未回写改动，flush 后清除', () {
    final cubit = ConsultCubit(
      makeTestTasks(),
      CacheService(filePath: ''),
      workspaceId: 'ws1',
      projectId: 'test',
    );
    addTearDown(cubit.close);
    expect(cubit.state.hasUnsavedChanges, false);

    cubit.toggleClarifyConfirm('o1');
    expect(cubit.state.hasUnsavedChanges, true);
  });
}

import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:http/http.dart' as http;
import 'package:qtconsult_studio/qtconsult_studio.dart';

const _workspacesJson = '[{"id":"ws1","name":"工作区A","project_ids":["p1"]}]';

const _projectJson = '''
{
  "id": "p1",
  "name": "p1",
  "title": "项目A",
  "tasks": [
    {"id": "t1", "title": "任务1", "type": "clarify", "tags": {}, "status": "pending"},
    {"id": "t2", "title": "任务2", "type": "execute", "tags": {}, "status": "pending"}
  ]
}
''';

class _MockClient extends http.BaseClient {
  final responses = <String, String>{
    'GET http://localhost:8756/workspaces': _workspacesJson,
    'GET http://localhost:8756/project/src/file149': _projectJson,
  };

  @override
  Future<http.StreamedResponse> send(http.BaseRequest request) async {
    final key = '${request.method} ${request.url}';
    final body = responses[key];
    if (body == null) {
      return http.StreamedResponse(const Stream<List<int>>.empty(), 404);
    }
    return http.StreamedResponse(
      http.ByteStream.fromBytes(utf8.encode(body)),
      200,
      headers: {'content-type': 'application/json; charset=utf-8'},
    );
  }
}

class _FailingClient extends http.BaseClient {
  @override
  Future<http.StreamedResponse> send(http.BaseRequest request) {
    return Future.error(Exception('provider down'));
  }
}

Future<String> _fileAsset(String path) async => File(path).readAsStringSync();

Future<String> _missingAsset(String path) async =>
    throw StateError('missing asset: $path');

CacheService _cacheFor(String wid, String pid) => CacheService(filePath: '');

AppCubit _cubit({ProviderService? provider, AssetLoader? loadAsset}) {
  return AppCubit(
    provider: provider,
    cacheBuilder: _cacheFor,
    loadAsset: loadAsset ?? _missingAsset,
  );
}

void main() {
  test('load 优先使用 provider 数据源', () async {
    final cubit = _cubit(
      provider: ProviderService(
        baseUrl: 'http://localhost:8756',
        client: _MockClient(),
      ),
    );
    addTearDown(cubit.close);

    await cubit.load();

    expect(cubit.state.status, AppStatus.success);
    expect(cubit.state.currentWsId, 'ws1');
    expect(cubit.state.currentProjectId, 'p1');
    expect(cubit.state.workspaces!.single.name, '工作区A');
    expect(cubit.state.project!.title, '项目A');
    expect(cubit.state.tasks, hasLength(2));
  });

  test('provider 不可用时回退 fixture', () async {
    final cubit = _cubit(
      provider: ProviderService(
        baseUrl: 'http://localhost:8756',
        client: _FailingClient(),
      ),
      loadAsset: _fileAsset,
    );
    addTearDown(cubit.close);

    await cubit.load();

    expect(cubit.state.status, AppStatus.success);
    expect(cubit.state.currentWsId, 'workspace0');
    expect(cubit.state.currentProjectId, 'project0');
    expect(cubit.state.project!.name, 'project0');
    expect(cubit.state.tasks, hasLength(18));
    expect(
      cubit.state.workspaces!.map((w) => w.id),
      ['workspace0', 'workspace1'],
    );
  });

  test('数据源全部失败进入 noData', () async {
    final cubit = _cubit();
    addTearDown(cubit.close);

    await cubit.load();

    expect(cubit.state.status, AppStatus.noData);
    expect(cubit.state.loadWarning, isNotNull);
    expect(cubit.state.workspaces, isNotNull);
  });

  test('切换工作区加载对应 fixture', () async {
    final cubit = _cubit(loadAsset: _fileAsset);
    addTearDown(cubit.close);

    await cubit.load();
    expect(cubit.state.currentWsId, 'workspace0');

    await cubit.switchWorkspace('workspace1');

    expect(cubit.state.status, AppStatus.success);
    expect(cubit.state.currentWsId, 'workspace1');
    expect(cubit.state.currentProjectId, 'project1');
    expect(cubit.state.project!.name, 'project1');
    expect(cubit.state.tasks, hasLength(20));
  });

  test('切换到当前工作区保持状态不变', () async {
    final cubit = _cubit(loadAsset: _fileAsset);
    addTearDown(cubit.close);

    await cubit.load();
    final before = cubit.state;

    await cubit.switchWorkspace('workspace0');

    expect(identical(cubit.state, before), isTrue);
  });

  test('切换到未知工作区保持状态不变', () async {
    final cubit = _cubit(loadAsset: _fileAsset);
    addTearDown(cubit.close);

    await cubit.load();
    final before = cubit.state;

    await cubit.switchWorkspace('nope');

    expect(identical(cubit.state, before), isTrue);
  });
}

