import 'package:flutter/material.dart';

import '../qtconsult_studio.dart';

/// 数据未就绪阶段的占位屏：加载中 / 加载失败 / 无可用数据。
///
/// 供 `HomeScreen`（`/`）与 `ProjectScreen`（`/:wid/:pid` 冷启动期）共用。
/// `success` 分支渲染加载占位——正常流程下它会被路由 `redirect` 抢先接管，
/// 仅作单帧防御，看板不在这里出现。
class PhasePlaceholder extends StatelessWidget {
  /// 创建阶段占位屏。
  const PhasePlaceholder({super.key, required this.state});

  /// 当前应用数据状态。
  final AppState state;

  @override
  Widget build(BuildContext context) {
    switch (state.status) {
      case AppStatus.failure:
        return const Scaffold(
          body: Center(
            child: Text('加载失败', style: TextStyle(color: Colors.red)),
          ),
        );
      case AppStatus.noData:
        return const Scaffold(
          body: Center(
            child: Text(
              '无可用的项目数据',
              style: TextStyle(color: Colors.red),
            ),
          ),
        );
      case AppStatus.loading:
      case AppStatus.success:
        return const Scaffold(
          body: Center(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                CircularProgressIndicator(),
                SizedBox(height: 16),
                Text(
                  '正在加载数据……',
                  style: TextStyle(color: Color(0xFF999999)),
                ),
              ],
            ),
          ),
        );
    }
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_bloc/flutter_bloc.dart';

import '../qtconsult_studio.dart';
import 'phase_placeholder.dart';

/// `/` 首页：只渲染数据未就绪的阶段占位。
///
/// 数据就绪后由路由表的 `redirect`（经 `refreshListenable` 触发）把 `/`
/// 归一化到具体项目路径 `/:wid/:pid`，看板由 `ProjectScreen` 承接——
/// 本组件不接触看板，`success` 单帧渲染占位等待 redirect 接管。
class HomeScreen extends StatelessWidget {
  /// 创建首页。
  const HomeScreen({super.key});

  @override
  Widget build(BuildContext context) {
    return BlocBuilder<AppCubit, AppState>(
      builder: (context, state) => PhasePlaceholder(state: state),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_bloc/flutter_bloc.dart';
import 'package:go_router/go_router.dart';

import '../qtconsult_studio.dart';
import 'phase_placeholder.dart';

/// `/:wid/:pid` 看板宿主：URL 与 [AppCubit] 状态单向对齐并渲染看板。
///
/// 同步只读取 go_router 的**当前** URI（不读任何 widget 参数），站内 `go`、
/// 浏览器前进后退、深链、过渡期新旧实例读数必然一致，不会互相拉扯——
/// URL 是「打开哪个项目」的唯一真相。冷启动深链在数据就绪前渲染
/// [PhasePlaceholder]；站内切换工作区由看板 AppBar 回调 `context.go` 改写 URL。
class ProjectScreen extends StatefulWidget {
  /// 创建看板宿主。
  const ProjectScreen({super.key});

  @override
  State<ProjectScreen> createState() => _ProjectScreenState();
}

class _ProjectScreenState extends State<ProjectScreen> {
  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    _syncRouteToCubit();
  }

  @override
  void didUpdateWidget(covariant ProjectScreen old) {
    super.didUpdateWidget(old);
    _syncRouteToCubit();
  }

  void _syncRouteToCubit() {
    if (!mounted) return;
    final router = GoRouter.maybeOf(context);
    if (router == null) return;
    final cubit = context.read<AppCubit>();
    final current = cubit.state;
    if (current.status != AppStatus.success) return;

    // 读原始路由信息而非 router.state：未匹配路径下 state 会因空 match list
    // 抛 `Bad state: No element`。
    final segments = router.routeInformationProvider.value.uri.pathSegments;
    if (segments.length != 2 || segments.any((s) => s.isEmpty)) return;
    final targetWid = segments[0];
    final targetPid = segments[1];
    if (current.currentWsId == targetWid &&
        current.currentProjectId == targetPid) {
      return;
    }
    cubit.openProject(targetWid, targetPid);
  }

  @override
  Widget build(BuildContext context) {
    return BlocListener<AppCubit, AppState>(
      listener: (context, state) => _syncRouteToCubit(),
      child: BlocBuilder<AppCubit, AppState>(
        builder: (context, state) {
          if (state.status != AppStatus.success) {
            return PhasePlaceholder(state: state);
          }
          return _BoardHost(state: state);
        },
      ),
    );
  }
}

class _BoardHost extends StatelessWidget {
  const _BoardHost({required this.state});

  final AppState state;

  @override
  Widget build(BuildContext context) {
    final project = state.project!;
    final tasks = state.tasks!;
    final pid = state.currentProjectId ?? project.name;
    return BlocProvider<ConsultCubit>(
      key: ValueKey('${state.currentWsId}:$pid'),
      create: (_) => ConsultCubit(
        tasks,
        state.cacheBuilder(state.currentWsId, pid),
        provider: state.provider,
        workspaceId: state.currentWsId,
        projectId: pid,
      ),
      child: ConsultBoardScreen(
        workspaces: state.workspaces,
        currentWsId: state.currentWsId,
        onSwitchWorkspace: state.workspaces == null
            ? null
            : (wid) {
                final matches = state.workspaces!.where((w) => w.id == wid);
                if (matches.isEmpty || matches.first.projectIds.isEmpty) {
                  return;
                }
                context.go(
                  '/$wid/${matches.first.projectIds.first}',
                );
              },
        loadWarning: state.loadWarning,
      ),
    );
  }
}

import 'dart:async';

import 'package:flutter/material.dart';
import 'package:go_router/go_router.dart';

import 'screens/home_screen.dart';
import 'screens/project_screen.dart';
import 'states/app_cubit.dart';

/// 路由表（平台契约：Studio 统一用 go_router）。
///
/// - `/`            阶段占位（加载中/失败/无数据）；数据就绪后经 `redirect`
///                  归一化到当前应展示的项目路径（`/` = 首个可用项目落地页）
/// - `/:wid/:pid`   项目看板宿主（深链与站内切换共用一条路径），冷启动数据
///                  未就绪时先渲染阶段占位
/// - 未知路径统一 `redirect` 回 `/`（`errorBuilder` 兜底）
///
/// 状态门通过 `redirect` + `refreshListenable` 实现：[AppCubit] 每次状态
/// 变化都触发重定向求值，视图层不再自行判断"该不该切页面"。
/// [initialLocation] 非空时用 `overridePlatformDefaultLocation` 强制生效：
/// Web 构建里平台默认路由会退化成 `/`（深链冷启动会落到默认项目），
/// 生产入口（`app.dart` 的 `_webInitialLocation`）从 `Uri.base` 取浏览器地址传进来。
GoRouter buildRouter({String? initialLocation, required AppCubit appCubit}) {
  return GoRouter(
    initialLocation: initialLocation,
    overridePlatformDefaultLocation: initialLocation != null,
    refreshListenable: _CubitRefresh(appCubit),
    redirect: (context, state) {
      final path = state.uri.path.isEmpty ? '/' : state.uri.path;
      final segments = state.uri.pathSegments;
      final known =
          path == '/' ||
